/*{	"DESCRIPTION": "Sets the alpha channel of the image",	"CREDIT": "VJRAYO",	"ISFVSN": "2",	"CATEGORIES": [		"MIX", "Transition"	],	"INPUTS": [		{			"NAME": "startImage",			"TYPE": "image"		},		{			"NAME": "endImage",			"TYPE": "image"		}	]}*/void main()	{	    vec4 base = IMG_THIS_PIXEL(startImage);        vec4 overlay = IMG_THIS_PIXEL(endImage);gl_FragColor = mix(base,overlay,overlay.a);}